<?php

declare(strict_types=1);
namespace App\Http\Requests\Pmbm;
use Illuminate\Foundation\Http\FormRequest;
use Illuminate\Validation\Rule;
class StoreApplicantRequest extends FormRequest {
 public function authorize(): bool{return true;}
 public function rules(): array { $choice=fn(array $v)=>['nullable','string',Rule::in($v)]; $life=['hidup','meninggal','tidak_diketahui']; $edu=['sd','smp','sma','d1','d2','d3','d4_s1','s2','s3','tidak_bersekolah']; $job=['tidak_bekerja','pensiunan','pns','tni_polisi','guru_dosen','pegawai_swasta','wiraswasta','hukum','seniman','medis','penerbangan','pedagang','petani','nelayan','buruh','transportasi','politikus','lainnya']; $income=['kurang_500k','500k_1jt','1jt_2jt','2jt_3jt','3jt_5jt','lebih_5jt','tidak_ada']; $r=['academic_year_id'=>'required|exists:academic_years,id','full_name'=>'required|string|max:200','nickname'=>'nullable|string|max:100','nik'=>'nullable|string|max:30','nisn'=>'nullable|string|max:30','citizenship'=>['required',Rule::in(['wni','wna'])],'gender'=>['required',Rule::in(['male','female'])],'birth_place'=>'required|string|max:150','birth_date'=>'required|date|before:today','religion'=>'required|string|max:50','aspiration'=>'nullable|string|max:100','child_order'=>'nullable|integer|min:1|max:99','sibling_count'=>'nullable|integer|min:0|max:99','origin_school'=>'nullable|string|max:200','origin_tk_ra'=>'nullable|string|max:200','address_street'=>'required|string|max:500','rt'=>'nullable|string|max:5','rw'=>'nullable|string|max:5','hamlet'=>'nullable|string|max:100','village'=>'required|string|max:150','district'=>'required|string|max:150','city'=>'required|string|max:150','province'=>'required|string|max:150','postal_code'=>'nullable|string|max:10','latitude'=>'nullable|numeric|between:-90,90','longitude'=>'nullable|numeric|between:-180,180','residence_status'=>'nullable|string|max:100','transportation'=>'nullable|string|max:100','distance_category'=>'nullable|string|max:50','travel_time'=>'nullable|string|max:50','school_funder'=>'nullable|string|max:100','family_card_number'=>'nullable|string|max:30','family_head_name'=>'nullable|string|max:200','special_needs'=>'nullable|string|max:150','special_needs_other'=>'required_if:special_needs,lainnya|nullable|string|max:500','health_notes'=>'nullable|string|max:1000','allergies'=>'nullable|string|max:500','support_needs'=>'nullable|string|max:1000','parent_email'=>'nullable|email|max:255','parent_phone'=>'required|string|max:30','guardian_type'=>['required',Rule::in(['father','mother','other'])],'consent'=>'accepted','documents'=>'nullable|array','documents.*'=>'nullable|file|mimes:jpg,jpeg,png,pdf|max:5120']; foreach(['father','mother'] as $p){$r["{$p}_name"]='required|string|max:200';$r["{$p}_status"]=['required',Rule::in($life)];foreach(['citizenship','birth_place','birth_date','education','job','income','phone','address','domicile','housing_status'] as $f)$r["{$p}_{$f}"]='nullable';$r["{$p}_citizenship"]=$choice(['wni','wna']);$r["{$p}_education"]=$choice($edu);$r["{$p}_job"]=$choice($job);$r["{$p}_income"]=$choice($income);$r["{$p}_birth_date"]='nullable|date|before:today';$r["{$p}_phone"]='nullable|string|max:30';$r["{$p}_address"]='nullable|string|max:500';$r["{$p}_domicile"]=$choice(['domestic','foreign']);$r["{$p}_housing_status"]='nullable|string|max:100';} foreach(['name','relationship','citizenship','birth_place','birth_date','education','job','income','phone','email','address','domicile'] as $f)$r["guardian_{$f}"]='nullable';$r['guardian_name']='required_if:guardian_type,other|nullable|string|max:200';$r['guardian_relationship']='required_if:guardian_type,other|nullable|string|max:100';$r['guardian_phone']='required_if:guardian_type,other|nullable|string|max:30';$r['guardian_email']='nullable|email|max:255';$r['guardian_birth_date']='nullable|date|before:today';$r['guardian_citizenship']=$choice(['wni','wna']);$r['guardian_education']=$choice($edu);$r['guardian_job']=$choice($job);$r['guardian_income']=$choice($income);$r['guardian_domicile']=$choice(['domestic','foreign']);$r['kks_number']='nullable|string|max:50';$r['pkh_number']='nullable|string|max:50'; return $r; }
 public function messages():array{return ['consent.accepted'=>'Pernyataan kebenaran data wajib disetujui.','special_needs_other.required_if'=>'Keterangan kebutuhan khusus wajib diisi.','guardian_name.required_if'=>'Nama wali lain wajib diisi.','documents.*.mimes'=>'Lampiran harus JPG, JPEG, PNG, atau PDF.','documents.*.max'=>'Ukuran lampiran maksimal 5 MB.'];}
}
